import jmespath.functions as f

fn = f.Functions()

# Correct behavior: a valid call with the right number of args succeeds.
result = fn.call_function('abs', [-5])
assert result == 5, "abs(-5) should return 5, got %r" % (result,)

# Correct behavior: wrong arg count must raise ArityError.
from jmespath import exceptions
try:
    fn.call_function('abs', [1, 2])
except exceptions.ArityError:
    pass
else:
    raise AssertionError("Wrong arity should raise ArityError")

print("OK")

import packaging.dependency_groups as dg

# A single, non-duplicated group must be accepted by the constructor.
groups = {"test": ["pytest"]}

try:
    resolver = dg.DependencyGroupResolver(groups)
except Exception as e:
    raise AssertionError(f"Constructor wrongly raised for non-duplicate groups: {e!r}")

result = resolver.resolve("test")
assert [str(r) for r in result] == ["pytest"], result

assert dg.resolve_dependency_groups(groups, "test") == ("pytest",)

# Genuine duplicates (differing non-normalized names) must still raise.
dup = {"my_group": ["a"], "my-group": ["b"]}
raised = False
try:
    dg.DependencyGroupResolver(dup)
except Exception:
    raised = True
assert raised, "Duplicate names should raise"

print("OK")

import yaml.representer as rep


class C:
    def __new__(cls, a=0):
        return object.__new__(cls)

    def __getnewargs__(self):
        return (1,)


obj = C(1)
obj.x = 5

r = rep.Representer()
node = r.represent_data(obj)

# Correct behavior: non-empty __new__ args with state must produce a
# python/object/new node with 'args' and 'state' keys, not a plain python/object.
assert node.tag.startswith('tag:yaml.org,2002:python/object/new:'), node.tag
keys = [k.value for k, v in node.value]
assert 'args' in keys and 'state' in keys, keys
print("ok")

import marshmallow.utils as u

# Test 1: dotted key should create nested dicts per the docstring
d = {}
try:
    u.set_value(d, 'foo.bar', 42)
except Exception as e:
    raise AssertionError(f"set_value raised on dotted key: {e!r}")
assert d == {'foo': {'bar': 42}}, f"Expected nested dict, got {d!r}"

# Test 2: undotted key should set directly
d2 = {}
try:
    u.set_value(d2, 'x', 1)
except Exception as e:
    raise AssertionError(f"set_value raised on undotted key: {e!r}")
assert d2 == {'x': 1}, f"Expected {{'x': 1}}, got {d2!r}"

print("OK")

import attr.converters as c

# Valid call with only default: spec says this should work and replace None.
try:
    conv = c.default_if_none(default=5)
except TypeError:
    raise AssertionError("default_if_none(default=5) wrongly raised TypeError")
assert conv(None) == 5
assert conv(3) == 3

# Valid call with only factory
try:
    conv2 = c.default_if_none(factory=list)
except TypeError:
    raise AssertionError("default_if_none(factory=list) wrongly raised TypeError")
assert conv2(None) == []
assert conv2(7) == 7

# Both passed must raise TypeError
try:
    c.default_if_none(default=1, factory=list)
except TypeError:
    pass
else:
    raise AssertionError("Passing both should raise TypeError")

# Neither passed must raise TypeError
try:
    c.default_if_none()
except TypeError:
    pass
else:
    raise AssertionError("Passing neither should raise TypeError")

import rich.protocol as mod

rich_cast = mod.rich_cast

# Plain string has no __rich__, so it should be returned unchanged.
try:
    result = rich_cast("hello")
except AttributeError as e:
    raise AssertionError(f"rich_cast raised AttributeError on plain string: {e}")
assert result == "hello", f"expected 'hello', got {result!r}"

# Plain object without __rich__ should also be returned unchanged.
class Plain:
    pass

p = Plain()
try:
    result = rich_cast(p)
except AttributeError as e:
    raise AssertionError(f"rich_cast raised AttributeError on plain object: {e}")
assert result is p, f"expected same object, got {result!r}"

# Object with __rich__ should be cast.
class WithRich:
    def __rich__(self):
        return "casted"

assert rich_cast(WithRich()) == "casted"

print("OK")

import rich.repr as rr


@rr.auto
class Foo:
    def __rich_repr__(self):
        yield "bar", 1


@rr.auto
class Baz:
    def __rich_repr__(self):
        yield "a", 1, 1   # equals default -> should be omitted
        yield "b", 2, 5   # differs from default -> should be shown


# (key, value) with no default must be shown
try:
    r1 = repr(Foo())
except Exception as e:
    raise AssertionError(f"repr raised {type(e).__name__}: {e}")
assert r1 == "Foo(bar=1)", f"expected 'Foo(bar=1)', got {r1!r}"

# (key, value, default): only omitted when value == default
try:
    r2 = repr(Baz())
except Exception as e:
    raise AssertionError(f"repr raised {type(e).__name__}: {e}")
assert r2 == "Baz(b=2)", f"expected 'Baz(b=2)', got {r2!r}"

print("OK")

import attr.converters as c


def conv(x: "int") -> "int":
    return int(x)


# Annotations are forward-reference strings, so `"int" | None` would raise TypeError.
try:
    opt = c.optional(conv)
except TypeError as e:
    raise AssertionError(f"optional() failed on string annotations: {e}")

assert opt(None) is None
assert opt("5") == 5
print("ok")
